import{_ as o,o as l,c as t,a5 as r}from"./chunks/framework.DvE3tBec.js";const a="/assets/processes.DhSFAAI1.png",m=JSON.parse('{"title":"Process Profiles","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/1.0/developers/profiles/processes.md","filePath":"documentation/1.0/developers/profiles/processes.md","lastUpdated":1702384098000}'),i={name:"documentation/1.0/developers/profiles/processes.md"};function c(s,e,d,n,u,g){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="process-profiles" tabindex="-1">Process Profiles <a class="header-anchor" href="#process-profiles" aria-label="Permalink to &quot;Process Profiles&quot;">​</a></h1><p>The following image provides an overview of the openEO Processes profiles. The minimal profile that allows an openEO implementation to be called &quot;openEO-compliant&quot; is <em>L1 Minimal</em>.</p><figure><img src="'+a+'" alt="The hierarchy of openEO Processes profiles: L1 Minimal -&gt; L2 Recommended (with sub-profiles) -&gt; L2A/B Raster/Vector -&gt; L3 Advanced (with sub-profiles) -&gt; L4 Above and Beyond"><figcaption>An overview of the openEO Processes profiles.</figcaption></figure><ul><li><em>L1 Minimal</em> ensures that the openEO implementation has a minimal set of functionality which allow users to execute basic use-cases.</li><li><em>L2 Recommended</em> add functionality that we recommend to be available so that users can more effectively make use of the openEO implementation.</li><li><em>L3 Advanced</em> allows users to execute more advanced use cases.</li><li><em>L4 Above and Beyond</em> adds very specific and complex requirements for very specific and highly advanced use cases.</li></ul><p>There are various sub-profiles in L2 (e.g., L2-Date) and L3 (e.g., L3-ML) that add a specific set of functionalities centered around specific needs such as date/time manipulation or execution of machine learning workflows.</p><p>In the following chapter you can find a list of requirements per profile.</p><h2 id="requirements-per-profile" tabindex="-1">Requirements per Profile <a class="header-anchor" href="#requirements-per-profile" aria-label="Permalink to &quot;Requirements per Profile&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Missing experimental processes should (by default) lead to a &quot;warning&quot;, but not lead to a rejection of that level in openEO.</p></div><h3 id="l1-minimal" tabindex="-1">L1: Minimal <a class="header-anchor" href="#l1-minimal" aria-label="Permalink to &quot;L1: Minimal&quot;">​</a></h3><ul><li><strong><code>absolute</code></strong></li><li><strong><code>add</code></strong></li><li><strong><code>and</code></strong></li><li><strong><code>apply</code></strong></li><li><strong><code>apply_dimension</code></strong><ul><li>All dimensions that your datacubes can include are supported - x and y can usually be excluded</li></ul></li><li><strong><code>arccos</code></strong></li><li><strong><code>arcsin</code></strong></li><li><strong><code>arctan</code></strong></li><li><strong><code>array_concat</code></strong></li><li><strong><code>array_create</code></strong></li><li><strong><code>array_element</code></strong></li><li><strong><code>between</code></strong></li><li><strong><code>ceil</code></strong></li><li><strong><code>clip</code></strong></li><li><strong><code>constant</code></strong></li><li><strong><code>cos</code></strong></li><li><strong><code>divide</code></strong></li><li><strong><code>e</code></strong></li><li><strong><code>eq</code></strong></li><li><strong><code>exp</code></strong></li><li><strong><code>first</code></strong></li><li><strong><code>floor</code></strong></li><li><strong><code>gt</code></strong></li><li><strong><code>gte</code></strong></li><li><strong><code>int</code></strong></li><li><strong><code>last</code></strong></li><li><strong><code>ln</code></strong></li><li><strong><code>load_collection</code></strong><ul><li>Parameter <code>temporal_extent</code>: All temporal formats are supported (date-time and date)</li></ul></li><li><strong><code>log</code></strong></li><li><strong><code>lt</code></strong></li><li><strong><code>lte</code></strong></li><li><strong><code>max</code></strong></li><li><strong><code>mean</code></strong></li><li><strong><code>median</code></strong></li><li><strong><code>min</code></strong></li><li><strong><code>mod</code></strong></li><li><strong><code>multiply</code></strong></li><li><strong><code>neq</code></strong></li><li><strong><code>not</code></strong></li><li><strong><code>or</code></strong></li><li><strong><code>pi</code></strong></li><li><strong><code>power</code></strong></li><li><strong><code>product</code></strong></li><li><strong><code>quantiles</code></strong></li><li><strong><code>reduce_dimension</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to L1) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li><li>Parameter <code>dimension</code>: All dimensions that your datacubes can include are supported - x and y are excluded as they are handled with reduce_spatial</li></ul></li><li><strong><code>round</code></strong></li><li><strong><code>save_result</code></strong></li><li><strong><code>sd</code></strong></li><li><strong><code>sgn</code></strong></li><li><strong><code>sin</code></strong></li><li><strong><code>sqrt</code></strong></li><li><strong><code>subtract</code></strong></li><li><strong><code>sum</code></strong></li><li><strong><code>tan</code></strong></li><li><strong><code>variance</code></strong></li></ul><h3 id="l2-recommended" tabindex="-1">L2: Recommended <a class="header-anchor" href="#l2-recommended" aria-label="Permalink to &quot;L2: Recommended&quot;">​</a></h3><ul><li><strong><code>add_dimension</code></strong><ul><li>Parameter <code>name</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>aggregate_temporal</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li><li>Parameter <code>reducer</code>: Supports access to labels in the callback</li><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>aggregate_temporal_period</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li><li>Parameter <code>reducer</code>: Supports access to labels in the callback</li><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li><li>Parameter <code>period</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>all</code></strong></li><li><strong><code>any</code></strong></li><li><strong><code>apply_dimension</code></strong><ul><li>Parameter <code>process</code>: Supports access to labels in the callback</li></ul></li><li><strong><code>arcosh</code></strong></li><li><strong><code>arctan2</code></strong></li><li><strong><code>array_element</code></strong><ul><li>Supports labeled arrays</li></ul></li><li><strong><code>array_find</code></strong></li><li><strong><code>arsinh</code></strong></li><li><strong><code>artanh</code></strong></li><li><strong><code>cosh</code></strong></li><li><strong><code>count</code></strong></li><li><strong><code>dimension_labels</code></strong><ul><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>drop_dimension</code></strong><ul><li>Parameter <code>name</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>extrema</code></strong></li><li><strong><code>filter_bbox</code></strong></li><li><strong><code>filter_temporal</code></strong><ul><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li><li>All temporal formats are supported (date-time and date)</li></ul></li><li><strong><code>if</code></strong></li><li><strong><code>inspect</code></strong> (experimental) <ul><li>Parameter <code>level</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>is_nan</code></strong></li><li><strong><code>is_nodata</code></strong></li><li><strong><code>is_valid</code></strong></li><li><strong><code>linear_scale_range</code></strong></li><li><strong><code>nan</code></strong> (experimental)</li><li><strong><code>normalized_difference</code></strong></li><li><strong><code>reduce_dimension</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to L2) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li><li>Parameter <code>reducer</code>: Supports access to labels in the callback</li></ul></li><li><strong><code>rename_dimension</code></strong></li><li><strong><code>rename_labels</code></strong><ul><li>Parameter <code>dimension</code>: All dimensions that your datacubes can include are supported - x and y can usually be excluded</li></ul></li><li><strong><code>sinh</code></strong></li><li><strong><code>sort</code></strong></li><li><strong><code>tanh</code></strong></li><li><strong><code>xor</code></strong></li></ul><h3 id="l2a-recommended-raster" tabindex="-1">L2A: Recommended Raster <a class="header-anchor" href="#l2a-recommended-raster" aria-label="Permalink to &quot;L2A: Recommended Raster&quot;">​</a></h3><ul><li><strong><code>aggregate_spatial</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li></ul></li><li><strong><code>apply_kernel</code></strong><ul><li>Parameter <code>border</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>filter_bands</code></strong><ul><li>Supports filtering by band name</li></ul></li><li><strong><code>filter_spatial</code></strong></li><li><strong><code>load_collection</code></strong><ul><li>Parameter <code>bands</code>: Supports filtering by band name and common name</li></ul></li><li><strong><code>mask</code></strong></li><li><strong><code>mask_polygon</code></strong></li><li><strong><code>resample_spatial</code></strong><ul><li>Parameter <code>method</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li></ul><h3 id="l2b-recommended-vector" tabindex="-1">L2B: Recommended Vector <a class="header-anchor" href="#l2b-recommended-vector" aria-label="Permalink to &quot;L2B: Recommended Vector&quot;">​</a></h3><ul><li><strong><code>filter_vector</code></strong> (experimental)</li><li><strong><code>vector_buffer</code></strong> (experimental)</li><li><strong><code>vector_reproject</code></strong> (experimental)</li></ul><h3 id="l2-date-date-time-manipulation" tabindex="-1">L2-Date: Date &amp; Time manipulation <a class="header-anchor" href="#l2-date-date-time-manipulation" aria-label="Permalink to &quot;L2-Date: Date &amp; Time manipulation&quot;">​</a></h3><ul><li><strong><code>date_between</code></strong> (experimental)</li><li><strong><code>date_difference</code></strong> (experimental)</li><li><strong><code>date_shift</code></strong> (experimental)</li></ul><h3 id="l2-text-text-manipulation" tabindex="-1">L2-Text: Text manipulation <a class="header-anchor" href="#l2-text-text-manipulation" aria-label="Permalink to &quot;L2-Text: Text manipulation&quot;">​</a></h3><ul><li><strong><code>text_begins</code></strong></li><li><strong><code>text_concat (text_merge)</code></strong></li><li><strong><code>text_contains</code></strong></li><li><strong><code>text_ends</code></strong></li></ul><h3 id="l3-advanced" tabindex="-1">L3: Advanced <a class="header-anchor" href="#l3-advanced" aria-label="Permalink to &quot;L3: Advanced&quot;">​</a></h3><ul><li><strong><code>add_dimension</code></strong><ul><li>Parameter <code>type</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>aggregate_spatial</code></strong><ul><li>Parameter <code>reducer</code>: Supports access to labels in the callback</li><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>aggregate_spatial_window</code></strong> (experimental)</li><li><strong><code>aggregate_temporal</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li><li>All temporal formats are supported (date-time, date and time)</li></ul></li><li><strong><code>aggregate_temporal_period</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>apply</code></strong><ul><li>Parameter <code>process</code>: At least all processes (up to the level of this requirement) in the categories <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>apply_dimension</code></strong><ul><li>Parameter <code>process</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>apply_neighborhood</code></strong><ul><li>Parameter <code>process</code>: Supports access to labels in the callback</li><li>Parameter <code>context</code>: is supported and passed to the callback</li><li>Parameter <code>data</code>: All listed label types supported.</li><li>Parameter <code>size</code> / <code>overlap</code>: Units <code>m</code>, <code>px</code> and <code>null</code> are supported</li></ul></li><li><strong><code>array_append</code></strong><ul><li>Supports labeled arrays</li></ul></li><li><strong><code>array_apply</code></strong><ul><li>Parameter <code>process</code>: Supports access to labels in the callback</li><li>Parameter <code>context</code>: is supported and passed to the callback</li><li>Supports labeled arrays</li></ul></li><li><strong><code>array_concat</code></strong><ul><li>Supports labeled arrays</li></ul></li><li><strong><code>array_contains</code></strong></li><li><strong><code>array_create_labeled</code></strong> (experimental)</li><li><strong><code>array_filter</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li><li>Supports labeled arrays</li></ul></li><li><strong><code>array_find_label</code></strong> (experimental)</li><li><strong><code>array_interpolate_linear</code></strong><ul><li>Supports labeled arrays</li></ul></li><li><strong><code>array_labels</code></strong></li><li><strong><code>array_modify</code></strong> (experimental) <ul><li>Supports labeled arrays</li></ul></li><li><strong><code>cloud_detection</code></strong> (experimental)</li><li><strong><code>count</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>create_data_cube (create_raster_cube)</code></strong></li><li><strong><code>cummax</code></strong> (experimental)</li><li><strong><code>cummin</code></strong> (experimental)</li><li><strong><code>cumproduct</code></strong> (experimental)</li><li><strong><code>cumsum</code></strong> (experimental)</li><li><strong><code>filter_bands</code></strong><ul><li>Supports filtering by common name</li></ul></li><li><strong><code>filter_labels</code></strong> (experimental) <ul><li>Parameter <code>context</code>: is supported and passed to the callback</li><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>flatten_dimensions</code></strong> (experimental)</li><li><strong><code>is_infinite</code></strong> (experimental)</li><li><strong><code>load_collection</code></strong><ul><li>Parameter <code>properties</code>: Supports querying by queryables defined via the API.</li></ul></li><li><strong><code>load_geojson</code></strong> (experimental)</li><li><strong><code>load_stac (load_result)</code></strong> (experimental) <ul><li>Supports loading from STAC API - Features.</li><li>Supports loading from STAC API - Item Search.</li><li>Supports loading from static STAC.</li><li>Parameter <code>temporal_extent</code>: All temporal formats are supported (date-time and date)</li><li>Parameter <code>bands</code>: Supports filtering by band name and common name</li></ul></li><li><strong><code>merge_cubes</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>ndvi</code></strong><ul><li>Supports common names as band names</li></ul></li><li><strong><code>order</code></strong></li><li><strong><code>rearrange</code></strong></li><li><strong><code>reduce_dimension</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>reduce_spatial</code></strong> (experimental) <ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the category <code>reducer</code> that accept an array as input and return a single value as output can be used (also in a chain of processes).</li><li>Parameter <code>reducer</code>: Supports access to labels in the callback</li><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>resample_cube_spatial</code></strong><ul><li>Parameter <code>method</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>resample_cube_temporal</code></strong><ul><li>Parameter <code>dimension</code>: All suitable dimensions are supported</li></ul></li><li><strong><code>resample_spatial</code></strong><ul><li>Parameter <code>align</code>: <code>enum</code> reflects implemention (all values are supported)</li></ul></li><li><strong><code>trim_cube</code></strong></li><li><strong><code>unflatten_dimensions</code></strong> (experimental)</li><li><strong><code>vector_to_random_points</code></strong> (experimental)</li><li><strong><code>vector_to_regular_points</code></strong> (experimental)</li></ul><h3 id="l3-ml-machine-learning" tabindex="-1">L3-ML: Machine Learning <a class="header-anchor" href="#l3-ml-machine-learning" aria-label="Permalink to &quot;L3-ML: Machine Learning&quot;">​</a></h3><ul><li><strong><code>fit_curve</code></strong> (experimental)</li><li><strong><code>fit_regr_random_forest</code></strong></li><li><strong><code>load_ml_model</code></strong> (experimental)</li><li><strong><code>predict_curve</code></strong> (experimental)</li><li><strong><code>save_ml_model</code></strong> (experimental)</li></ul><h3 id="l3-udf-user-defined-functions" tabindex="-1">L3-UDF: User-Defined Functions <a class="header-anchor" href="#l3-udf-user-defined-functions" aria-label="Permalink to &quot;L3-UDF: User-Defined Functions&quot;">​</a></h3><ul><li><strong><code>run_udf</code></strong><ul><li>Parameter <code>context</code>: is supported and passed to the callback</li></ul></li><li><strong><code>run_udf_externally</code></strong> (experimental)</li></ul><h3 id="l3-clim-cimatology" tabindex="-1">L3-Clim: Cimatology <a class="header-anchor" href="#l3-clim-cimatology" aria-label="Permalink to &quot;L3-Clim: Cimatology&quot;">​</a></h3><ul><li><strong><code>anomaly</code></strong></li><li><strong><code>climatological_normal</code></strong></li></ul><h3 id="l3-ard-analysis-ready-data" tabindex="-1">L3-ARD: Analysis-Ready Data <a class="header-anchor" href="#l3-ard-analysis-ready-data" aria-label="Permalink to &quot;L3-ARD: Analysis-Ready Data&quot;">​</a></h3><ul><li><strong><code>ard_normalized_radar_backscatter</code></strong> (experimental) <ul><li>has been tested on &gt; 100x100km at 10m resolution (or equivalent)</li><li>Custom parameters are provided via the <code>options</code> parameter</li></ul></li><li><strong><code>ard_surface_reflectance</code></strong> (experimental) <ul><li>Parameter <code>atmospheric_correction_method</code>: <code>enum</code> reflects implemention (all values are supported)</li><li>Parameter <code>cloud_detection_method</code>: <code>enum</code> reflects implemention (all values are supported)</li><li>Custom parameters are provided via the <code>atmospheric_correction_options</code> and/or <code>cloud_detection_options</code> parameters</li></ul></li></ul><h3 id="l4-above-and-beyond" tabindex="-1">L4: Above and Beyond <a class="header-anchor" href="#l4-above-and-beyond" aria-label="Permalink to &quot;L4: Above and Beyond&quot;">​</a></h3><ul><li><strong><code>aggregate_spatial</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>aggregate_temporal</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>aggregate_temporal_period</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>apply_neighborhood</code></strong><ul><li>Parameter <code>process</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>apply_polygon (chunk_polygon)</code></strong> (experimental)</li><li><strong><code>array_apply</code></strong><ul><li>Parameter <code>process</code>: At least all processes (up to the level of this requirement) in the categories <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>atmospheric_correction</code></strong> (experimental) <ul><li>Parameter <code>method</code>: <code>enum</code> reflects implemention (all values are supported)</li><li>Custom parameters are provided via the <code>options</code> parameter</li></ul></li><li><strong><code>filter_bands</code></strong><ul><li>Supports filtering by wavelength</li></ul></li><li><strong><code>filter_bbox</code></strong><ul><li>Parameter <code>extent</code>: Supports filtering by base/height</li></ul></li><li><strong><code>load_collection</code></strong><ul><li>Parameter <code>spatial_extent</code>: Supports filtering by base/height</li></ul></li><li><strong><code>load_stac (load_result)</code></strong> (experimental) <ul><li>Parameter <code>spatial_extent</code>: Supports filtering by base/height</li></ul></li><li><strong><code>load_uploaded_files</code></strong> (experimental)</li><li><strong><code>load_url</code></strong> (experimental)</li><li><strong><code>reduce_dimension</code></strong><ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>reduce_spatial</code></strong> (experimental) <ul><li>Parameter <code>reducer</code>: At least all processes (up to the level of this requirement) in the categories <code>array</code>, <code>comparison</code>, <code>logic</code> and <code>math</code> can be used (also in a chain of processes).</li></ul></li><li><strong><code>sar_backscatter</code></strong> (experimental) <ul><li>Parameter <code>coefficient</code>: <code>enum</code> reflects implemention (all values are supported)</li><li>Custom parameters are provided via the <code>options</code> parameter</li></ul></li></ul>',32)])])}const h=o(i,[["render",c]]);export{m as __pageData,h as default};
